CREATE TEMPORARY VIEW user_exp_mapping_${grass_region_without_quote} AS
SELECT
    user_id
    ,CAST(abtest_group AS BIGINT) AS exp_group_id
FROM
    video.video_mart_dim_abtest_user_group_v2_di
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND scene_key IN ('video_union', 'paidads_universal','global_priority')
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW request_advv_benchmark_preprocess_${grass_region_without_quote} AS
SELECT
    -- Preprocess data to original srdi_mart.dws_sr_request_level_ads_type_advv_di dimensions
    feature_group
    ,user_id
    ,request_id
    ,product_type
    ,ads_id
    ,item_id
    ,campaign_id

    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(broad_gmv_usd) AS broad_gmv_usd
    ,SUM(ads_gmv_usd) AS ads_gmv_usd
    ,MAX(target_cir) AS target_cir
    ,SUM(direct_advv_cost) AS direct_advv_cost
    ,SUM(broad_advv_cost) AS broad_advv_cost
    ,SUM(direct_advv_gmv) AS direct_advv_gmv
    ,SUM(broad_advv_gmv) AS broad_advv_gmv
    ,MAX(sum_deduction_price_usd) AS sum_deduction_price_usd
    ,MAX(sum_bid_price_usd) AS sum_bid_price_usd
    ,MAX(cnt_deduction_price) AS cnt_deduction_price
    ,MAX(cnt_bid_price) AS cnt_bid_price
FROM
    srdi_mart.dws_sr_data_warehouse_ads_request_benchmark_advv_1d
LATERAL VIEW
    EXPLODE(feature_groups) AS feature_group   
LATERAL VIEW
    EXPLODE(product_types) AS product_type
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
GROUP BY
    1,2,3,4,5,6,7;

--sql_divide_splitter--

CREATE TEMPORARY VIEW request_advv_benchmark_explode_${grass_region_without_quote} AS
SELECT
    user_id
    ,feature_group AS feature_group_chained
    ,product_type

    ,revenue_usd
    ,broad_gmv_usd
    ,ads_gmv_usd
    ,target_cir
    ,direct_advv_cost
    ,broad_advv_cost
    ,direct_advv_gmv
    ,broad_advv_gmv
    ,sum_deduction_price_usd
    ,sum_bid_price_usd
    ,cnt_deduction_price
    ,cnt_bid_price
FROM
    request_advv_benchmark_preprocess_${grass_region_without_quote}
WHERE
    feature_group IN (
        'video_trending#video_rcmd_core#trending_video_internal_all#trending_hp_internal#video_rcmd_all#video_all'
        ,'dd_video_internal#trending_video_internal_all#dd_video#video_rcmd_core#video_rcmd_all#video_all'
        ,'homepage_video_external#homepage_video#video_rcmd_core#video_rcmd_all#video_all'
        ,'homepage_video_internal#trending_video_internal_all#trending_hp_internal#homepage_video#video_rcmd_core#video_rcmd_all#video_all'
        ,'dd_video_external#dd_video#video_rcmd_core#video_rcmd_all#video_all'
    )
    AND product_type NOT IN ('simple_mode_boost', 'roi2.0_simple (organic)', 'roi2.0_simple (ads)', '__ALL__');

--sql_divide_splitter--

CREATE TEMPORARY VIEW advv_request_flatten_join_exp_${grass_region_without_quote} AS
SELECT
    rcmd_ab_bundle
    ,product_type
    ,exp_group_id
    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(broad_gmv_usd) AS broad_gmv_usd
    ,SUM(ads_gmv_usd) AS ads_gmv_usd
    ,AVG(target_cir) AS target_cir
    ,SUM(direct_advv_cost) AS direct_advv_cost
    ,SUM(broad_advv_cost) AS broad_advv_cost
    ,SUM(direct_advv_gmv) AS direct_advv_gmv
    ,SUM(broad_advv_gmv) AS broad_advv_gmv
    ,CASE
        WHEN product_type IN ('manual_cpc','manual_ecpc','itemboost','new_product_boost') THEN SUM(ads_gmv_usd)
        WHEN product_type IN ('simple_ocpc','autoboost','roi2.0','simple_roas', 'roi2.0_simple') AND rcmd_ab_bundle != 'Search' THEN SUM(direct_advv_gmv) -- 新增'roi2.0_simple'
        ELSE 0.0000000001
    END AS denominator_direct_gmv_ratio
    ,CASE
        WHEN product_type IN ('manual_cpc','manual_ecpc','itemboost','new_product_boost') THEN SUM(broad_gmv_usd)
        WHEN product_type IN ('simple_ocpc','autoboost','roi2.0','simple_roas','roi2.0_simple') AND rcmd_ab_bundle != 'Search' THEN SUM(broad_advv_gmv) -- 新增'roi2.0_simple'
        ELSE 0.0000000001
    END AS denominator_broad_gmv_ratio
    ,SUM(sum_deduction_price_usd) AS sum_deduction_price_usd
    ,SUM(sum_bid_price_usd) AS sum_bid_price_usd
    ,SUM(cnt_deduction_price) AS cnt_deduction_price
    ,SUM(cnt_bid_price) AS cnt_bid_price
FROM
    request_advv_benchmark_explode_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
LATERAL VIEW
    EXPLODE(SPLIT(feature_group_chained, '#')) AS rcmd_ab_bundle
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_metrics_${grass_region_without_quote} AS
SELECT
    rcmd_ab_bundle
    ,CASE
        WHEN product_type IN ('manual_cpc','manual_ecpc', 'itemboost', 'simple_ocpc', 'autoboost', 'simple_roas', 'new_product_boost') THEN 'ROI 1.0'
        WHEN product_type IN ('roi2.0') THEN 'ROI 2.0'
        WHEN product_type IN ('roi2.0_simple') THEN 'Simple Ads 2.0' -- view roi2.0 and simple2.0 seperately feb 2025
        ELSE 'others'
    END AS roi_type
    ,exp_group_id
    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(broad_gmv_usd) AS broad_gmv_usd
    ,SUM(ads_gmv_usd) AS ads_gmv_usd
    ,AVG(target_cir) AS target_cir
    ,SUM(direct_advv_cost) AS direct_advv_cost
    ,SUM(broad_advv_cost) AS broad_advv_cost
    ,SUM(direct_advv_gmv) AS direct_advv_gmv
    ,SUM(broad_advv_gmv) AS broad_advv_gmv
    ,SUM(revenue_usd) / SUM(direct_advv_cost) AS direct_cost_ratio
    ,SUM(revenue_usd) / SUM(broad_advv_cost) AS broad_cost_ratio
    ,SUM(ads_gmv_usd) / SUM(denominator_direct_gmv_ratio) AS direct_gmv_ratio
    ,SUM(broad_gmv_usd) / SUM(denominator_broad_gmv_ratio) AS broad_gmv_ratio
    ,SUM(sum_deduction_price_usd)/SUM(cnt_deduction_price) AS avg_deduction_price_usd
    ,SUM(sum_bid_price_usd)/SUM(cnt_bid_price) AS avg_bid_price_usd
    ,SUM(sum_deduction_price_usd) AS sum_deduction_price_usd
    ,SUM(sum_bid_price_usd) AS sum_bid_price_usd
    ,SUM(cnt_deduction_price) AS cnt_deduction_price
    ,SUM(cnt_bid_price) AS cnt_bid_price
    ,(SUM(sum_deduction_price_usd)/SUM(cnt_deduction_price))/(SUM(sum_bid_price_usd)/SUM(cnt_bid_price)) AS deduction_bid_ratio
FROM
    advv_request_flatten_join_exp_${grass_region_without_quote}
GROUP BY
    1,2,3
UNION ALL
SELECT
    rcmd_ab_bundle
    ,'Ads ROI' AS roi_type
    ,exp_group_id
    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(broad_gmv_usd) AS broad_gmv_usd
    ,SUM(ads_gmv_usd) AS ads_gmv_usd
    ,AVG(target_cir) AS target_cir
    ,SUM(direct_advv_cost) AS direct_advv_cost
    ,SUM(broad_advv_cost) AS broad_advv_cost
    ,SUM(direct_advv_gmv) AS direct_advv_gmv
    ,SUM(broad_advv_gmv) AS broad_advv_gmv
    ,SUM(revenue_usd) / SUM(direct_advv_cost) AS direct_cost_ratio
    ,SUM(revenue_usd) / SUM(broad_advv_cost) AS broad_cost_ratio
    ,SUM(ads_gmv_usd) / SUM(denominator_direct_gmv_ratio) AS direct_gmv_ratio
    ,SUM(broad_gmv_usd) / SUM(denominator_broad_gmv_ratio) AS broad_gmv_ratio
    ,SUM(sum_deduction_price_usd)/SUM(cnt_deduction_price) AS avg_deduction_price_usd
    ,SUM(sum_bid_price_usd)/SUM(cnt_bid_price) AS avg_bid_price_usd
    ,SUM(sum_deduction_price_usd) AS sum_deduction_price_usd
    ,SUM(sum_bid_price_usd) AS sum_bid_price_usd
    ,SUM(cnt_deduction_price) AS cnt_deduction_price
    ,SUM(cnt_bid_price) AS cnt_bid_price
    ,(SUM(sum_deduction_price_usd)/SUM(cnt_deduction_price))/(SUM(sum_bid_price_usd)/SUM(cnt_bid_price)) AS deduction_bid_ratio
FROM
    advv_request_flatten_join_exp_${grass_region_without_quote}
GROUP BY
    1,2,3;

